        wv(22, .wirtschaft, "Die Sachs-IT GmbH kauft Waren, die in weltweiter Arbeitsteilung hergestellt werden.\nWelche der folgenden Auswirkungen hat die weltweite Arbeitsteilung?",
           ["Durch Nutzung der jeweils wirtschaftlich günstigsten Rohstoff- und Produktionsbedingungen nimmt die Menge der transportierten Waren weltweit zu.", "Die Produktion erfolgt jeweils in den Ländern mit den ökologisch besten Standards.", "Aufgrund internationaler Vereinbarungen müssen die Unternehmen in allen Ländern die gleichen hohen sozialen und ökologischen Standards einhalten.", "Die Volkswirtschaften der Länder spezialisieren sich nicht auf bestimmte Produktionen.", "Auf dem weltweiten Arbeitsmarkt herrscht eine allgemeine Arbeitnehmerfreizügigkeit."],
           "Ziffer 2."),
        ihkMatch("ihk-ap2-2022s-wiso-23", .schutz, s22wLage,
                 "23. Aufgabe\nHerr Petry wird von der Sicherheitsfachkraft der Sachs-IT GmbH über Schutzmaßnahmen am Arbeitsplatz informiert. Dabei legt die Sicherheitsfachkraft Wert darauf, dass die Sicherheitskennzeichen bekannt sind.\nWelche der folgenden Sicherheitskennzeichen sind den danebenstehenden Bedeutungen zuzuordnen?\n[Abbildung als Text, Sicherheitskennzeichen: 1 Quadrat mit einer Hand, die einen Melder drückt, und Flammen; 2 Warndreieck mit Flamme; 3 Warndreieck mit Blitz; 4 Verbotskreis mit einer Hand vor einer Person; 5 Quadrat mit Pfeil nach rechts; 6 Verbotskreis mit Hand und Blitz; 7 Quadrat mit einer Personengruppe und vier nach innen gerichteten Pfeilen]",
                 pairs: [("a) Warnung vor feuergefährlichen Stoffen", "Zeichen 2 (Warndreieck mit Flamme)"),
                         ("b) Gehäuse unter Spannung, nicht berühren", "Zeichen 6 (Verbotskreis mit Hand und Blitz)"),
                         ("c) Manueller Brandmelder", "Zeichen 1 (Hand drückt Melder, Flammen)"),
                         ("d) Richtungsangabe Rettungsweg", "Zeichen 5 (Pfeil nach rechts)")],
                 extra: ["Zeichen 3 (Warndreieck mit Blitz)", "Zeichen 4 (Verbotskreis mit Hand vor einer Person)", "Zeichen 7 (Personengruppe mit vier Pfeilen)"],
                 "\(s22wMuster) a) 2, b) 6, c) 1, d) 5."),
        wv(24, .schutz, "Die Mitarbeitenden der Sachs-IT GmbH müssen die Vorschriften zu Unfallverhütung und zum Arbeits- und zum Gesundheitsschutz am Arbeitsplatz kennen und einhalten.\nWelche der folgenden Aussagen trifft auf die Informationspflicht über Unfallverhütungsvorschriften zu?\nDie Sachs-IT GmbH muss …",
           ["die Unfallverhütungsvorschriften im Betrieb gut sichtbar aushängen.", "ihre Mitarbeiter schriftlich informieren, dass an den Arbeitsplätzen Unfallverhütungsvorschriften einzuhalten sind, die sie bei der zuständigen Berufsgenossenschaft einsehen können.", "ihre Mitarbeiter zu Beginn ihrer Tätigkeit einmal mündlich, z. B. im Vorstellungsgespräch, über die einzuhaltenden Unfallverhütungsvorschriften informieren.", "die Unfallverhütungsvorschriften im Intranet bereitstellen, sodass alle Mitarbeiter diese jederzeit einsehen und downloaden können.", "jeden neuen Mitarbeiter zu einer Informationsveranstaltung über Arbeitssicherheit und Gesundheitsschutz bei der zuständigen Berufsgenossenschaft anmelden."],
           "Ziffer 4. Hinweis: § 12 DGUV Vorschrift 1 verlangt nur, die Vorschriften an geeigneter Stelle zugänglich zu machen; ein jederzeit erreichbares Intranet kann das heute ebenfalls erfüllen."),
        wv(25, .schutz, "Herrn Petry liegen die folgenden Piktogramme, die das Löschen mithilfe von Feuerlöschgeräten zum Thema haben, vor. Eine Kollegin meint, dass eins der Piktogramme ein unzutreffendes Verhalten darstellt.\nWelches der folgenden Piktogramme stellt unzutreffendes Verhalten im Löschfall dar?\n[Abbildung als Text: fünf Piktogramme, jeweils eine Person mit Feuerlöscher beim Löschen; die Bildunterschriften sind die folgenden Antworten.]",
           ["Tropf- und Fließbrände von unten bekämpfen, NIE von oben löschen", "Brandstelle beobachten, auf Wiederentzündung warten, NICHT einfach weggehen", "Möglichst viele Feuerlöscher gleichzeitig benutzen, NICHT hintereinander", "Von unten und von vorn nach hinten löschen, NICHT andersherum", "Immer in Windrichtung löschen, NICHT gegen den Wind"],
           "Ziffer 3. Richtig ist das Gegenteil: Tropf- und Fließbrände von oben nach unten löschen. Die übrigen vier Piktogramme zeigen zutreffendes Verhalten."),
        ihkOrder("ihk-ap2-2022s-wiso-26", .schutz, s22wLage,
                 "26. Aufgabe\nZur Brandbekämpfung verwendet die Sachs-IT GmbH u. a. Feuerlöscher. Herr Petry weist die Auszubildenden in die Handhabung der Feuerlöscher mit Dauerdruck ein.\nBringen Sie die folgenden Schritte zur Bedienung eines Feuerlöschers in die richtige Reihenfolge.",
                 steps: ["Zum Feuerlöschgerät laufen", "Feuerlöscher aus der Wandhalterung entnehmen", "Sicherungsstift/Sicherungslasche ziehen", "Betätigungshebel ziehen/Betätigungstaste drücken", "Schlauch in Richtung Feuer halten"],
                 "\(s22wMuster) Zum Feuerlöschgerät laufen, aus der Wandhalterung entnehmen, Sicherungsstift ziehen, Betätigungshebel ziehen, Schlauch in Richtung Feuer halten. Hinweis: In der Praxis richtet man den Schlauch schon vor dem Betätigen des Hebels auf das Feuer."),
        wv(27, .nachhaltigkeit, "Im Rahmen des Umweltschutzes soll künftig stärker das Verursacherprinzip berücksichtigt werden.\nWelche der folgenden Aussagen zum Verursacherprinzip trifft zu?\nDas Verursacherprinzip bedeutet, dass …",
           ["die Kosten für die Beseitigung von Umweltschäden diejenigen tragen, die für die Schäden verantwortlich sind.", "die Kosten für die Beseitigung von Umweltschäden auf alle Mitglieder der Solidargemeinschaft gleichmäßig aufgeteilt werden.", "möglichst solche Waren vertrieben werden sollen, deren Verpackung vom Konsumenten leicht fachgerecht entsorgt werden kann.", "die Abfallentsorgung wichtiger ist als die Abfallvermeidung.", "ausreichend Verpackungsmaterial eingesetzt wird, damit die Ware nicht beschädigt wird."],
           "Ziffer 2."),
        wv(28, .nachhaltigkeit, "Zweck des Kreislaufwirtschaftsgesetzes ist es unter anderem, das Recycling von Abfällen zu fördern.\nWelche der folgenden Handlungen im Betriebsablauf der Sachs-IT GmbH wird als Recycling bezeichnet?",
           ["Anfallende Verpackungen werden erst nach Materialien getrennt und dann dem Dualen System zugeführt.", "Die Sachs-IT GmbH verwendet für Verpackungen bei Briefen und Paketen nur Materialien mit dem Umweltsiegel.", "In den Waschräumen werden Papierhandtücher bereitgelegt, die besonders hygienisch sind.", "Durch den Einbau von Öko-Toiletten-Spülungen wird wertvolles Trinkwasser gespart.", "In der Kantine werden nur Lebensmittel aus biologischer Erzeugung verwendet."],
           "Ziffer 3."),
        wv(29, .recht, "Die Sachs-IT GmbH möchte ihr „Diversity Management“ neu bewerten und überlegt, der 2006 ins Leben gerufenen „Charta der Vielfalt“ beizutreten. Hierbei handelt es sich um eine Selbstverpflichtung von Unternehmen und anderen Organisationen, ein möglichst vorurteilsfreies Arbeitsumfeld zu schaffen.\nWelcher der folgenden Punkte wird in der Charta nicht berücksichtigt?",
           ["Ausbildungsstand/Art des Abschlusses", "Alter", "Religion", "Sexuelle Orientierung/Identität", "Nationalität/ethnische Herkunft"],
           "Ziffer 4."),
        wv(30, .arbeitsrecht, "Ihr Kollege möchte sich näher mit dem Thema beschäftigen und fragt Sie, was das Ziel des Diversity Managements ist.\nWelche der folgenden Antworten geben Sie ihm?\nDiversity Management …",
           ["will die in der Vielfalt der Belegschaft liegenden Potenziale für das Unternehmen nutzbar machen.", "ist ein klassischer Teil des Personalwesens und soll die bestehenden Vorurteile bei Kunden ausnutzen.", "zielt auf eine Gewinnmaximierung durch Personaleinsparung ab.", "umfasst alle Strategien, die es erlauben, Ungleiches gleich und Gleiches ungleich zu behandeln.", "soll helfen, dass Humankapital der Belegschaft dem Management zur Verfügung zu stellen."],
           "Ziffer 5."),
    ]
}
